import struct
import sys

import numpy as np
import wgpu

SHADER = """
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    pad: u32,
    x_min: f32,
    dx: f32,
    y_min: f32,
    dy: f32,
};

@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read_write> out: array<u32>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= p.width || id.y >= p.height) {
        return;
    }
    let cx = p.x_min + (f32(id.x) + 0.5) * p.dx;
    let cy = p.y_min + (f32(id.y) + 0.5) * p.dy;
    var zx: f32 = 0.0;
    var zy: f32 = 0.0;
    var n: u32 = 0u;
    loop {
        if (n >= p.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let t = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = t;
        n = n + 1u;
    }
    out[id.y * p.width + id.x] = n;
}
"""


def escape_times(width, height, limit, x_min, x_max, y_min, y_max):
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()
    count = width * height
    params = struct.pack(
        "<4I4f",
        width,
        height,
        limit,
        0,
        x_min,
        (x_max - x_min) / width,
        y_min,
        (y_max - y_min) / height,
    )
    ubuf = device.create_buffer_with_data(data=params, usage=wgpu.BufferUsage.UNIFORM)
    obuf = device.create_buffer(
        size=count * 4,
        usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
    )
    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    group = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": ubuf, "offset": 0, "size": ubuf.size}},
            {"binding": 1, "resource": {"buffer": obuf, "offset": 0, "size": obuf.size}},
        ],
    )
    enc = device.create_command_encoder()
    cpass = enc.begin_compute_pass()
    cpass.set_pipeline(pipeline)
    cpass.set_bind_group(0, group)
    cpass.dispatch_workgroups((width + 7) // 8, (height + 7) // 8, 1)
    cpass.end()
    device.queue.submit([enc.finish()])
    data = device.queue.read_buffer(obuf)
    return np.frombuffer(data, dtype=np.uint32, count=count)


def main():
    with open(sys.argv[1]) as f:
        tokens = f.read().split()
    width, height, limit = int(tokens[0]), int(tokens[1]), int(tokens[2])
    x_min, x_max, y_min, y_max = (float(t) for t in tokens[3:7])

    t = escape_times(width, height, limit, x_min, x_max, y_min, y_max)

    inside = int(np.count_nonzero(t >= limit))
    esc = t[t < limit].astype(np.int64)
    bins = np.bincount((8 * esc) // limit, minlength=8)[:8]
    mean = float(esc.sum()) / len(esc) if len(esc) else 0.0

    out = [f"INSIDE {inside}"]
    out += [f"BIN {k} {int(bins[k])}" for k in range(8)]
    out.append(f"MEAN {mean:.3f}")
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
